function trackOpen(uri, text, version, languageId) {
  const p = toPath(uri);
  openDocs.set(uri, {
    version: typeof version === 'number' ? version : 1,
    text: text != null ? text : '',
    languageId: languageId || 'plaintext',
    path: p,
    stat: p ? statOf(p) : null,
    pending: false,
    missing: false,
    closed: false,
    unsyncable: false,
  });
}

