    }

    for (const entry of entries) {
      if (excludeSet.has(entry.name)) continue;

      const fullPath = join(dir, entry.name);
      if (entry.isDirectory()) {
        stack.push(fullPath);
      } else if (entry.isFile() && extSet.has(extname(entry.name))) {
        results.push(fullPath);
      }
    }
  }
  return results;
}

