function toPath(uri) {
  try {
    return uri?.startsWith('file:') ? fileURLToPath(uri) : null;
  } catch {
    return null;
  }
}

regal-lsp/lsp-proxy.js::statOf.source_code:
function statOf(p) {
  try {
    const s = statSync(p);
    return { mtimeMs: s.mtimeMs, ctimeMs: s.ctimeMs, size: s.size, ino: s.ino };
  } catch {
    return null;
  }
}

regal-lsp/lsp-proxy.js::sameStat.source_code:
function sameStat(a, b) {
  return (
    a &&
    b &&
    a.mtimeMs === b.mtimeMs &&
    a.ctimeMs === b.ctimeMs &&
    a.size === b.size &&
    a.ino === b.ino
  );
}

regal-lsp/lsp-proxy.js::trackOpen.source_code:
function trackOpen(uri, text, version, languageId) {
  const p = toPath(uri);
  openDocs.set(uri, {
    version: typeof version === 'number' ? version : 1,
    text: text != null ? text : '',
    languageId: languageId || 'plaintext',
    path: p,
    stat: p ? statOf(p) : null,
    pending: false,
    missing: false,
    closed: false,
    unsyncable: false,
  });
}

